import{H as e,V as t,et as n,j as r}from"./chunks/framework.c0x6U8zS.js";var i=JSON.parse(`{"title":"AHE01 变量说明（可通过 APP 配置）","description":"","frontmatter":{},"headers":[],"relativePath":"products/ahe01/app-vars.md","filePath":"products/ahe01/app-vars.md","lastUpdated":1786806641000}`),a={name:`products/ahe01/app-vars.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="ahe01-变量说明-可通过-app-配置" tabindex="-1">AHE01 变量说明（可通过 APP 配置） <a class="header-anchor" href="#ahe01-变量说明-可通过-app-配置" aria-label="Permalink to “AHE01 变量说明（可通过 APP 配置）”">​</a></h1><p>对应 BLE 命令 <strong>参数寄存器 1</strong>（<code>0xFA</code>，14 字节）。空中布局与读写见 <a href="./ble-protocol.html">AHE01 BLE 协议</a> §2.8。</p><p>多字节一律 <strong>大端</strong>。<code>[13]</code> 为保留字节，不要当功能用。</p><h2 id="智能匹配算法变量" tabindex="-1">智能匹配算法变量 <a class="header-anchor" href="#智能匹配算法变量" aria-label="Permalink to “智能匹配算法变量”">​</a></h2><p>主要用于算法逻辑调试和可配置。</p><table tabindex="0"><thead><tr><th>偏移</th><th>变量名</th><th>默认值</th></tr></thead><tbody><tr><td><code>[0]</code></td><td><code>cali_pressure_increase_percent</code></td><td>5%</td></tr><tr><td><code>[1]</code></td><td><code>cali_pressure_decrease_percent</code></td><td>5%</td></tr><tr><td><code>[2-3]</code></td><td><code>max_pressure_protect_value</code></td><td>出厂确认</td></tr><tr><td><code>[4]</code></td><td><code>pressure_sample_period</code></td><td>5 秒</td></tr><tr><td><code>[5]</code></td><td><code>pressure_stable_percent</code></td><td>±10%</td></tr><tr><td><code>[6]</code></td><td><code>pressure_stable_duration</code></td><td>5 秒</td></tr><tr><td><code>[7]</code></td><td><code>total_adjust_count_per_sleep</code></td><td>0（不限次数）</td></tr><tr><td><code>[8]</code></td><td><code>base_pillow_height</code></td><td>第一次使用用户选择</td></tr></tbody></table><h4 id="_0-cali-pressure-increase-percent" tabindex="-1"><code>[0]</code> <code>cali_pressure_increase_percent</code> <a class="header-anchor" href="#_0-cali-pressure-increase-percent" aria-label="Permalink to “[0] cali_pressure_increase_percent”">​</a></h4><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>类别</td><td>工程变量</td></tr><tr><td>含义</td><td>标定的两次枕高压强变化<strong>正向百分比</strong>（压强增加时，P2≥P1）</td></tr><tr><td>默认值</td><td>5%</td></tr><tr><td>取值范围</td><td>0–100（整数）</td></tr><tr><td>数据类型</td><td>1 字节整数</td></tr><tr><td>用途</td><td>与两次枕高压强变化率 <code>(P2-P1)/P1</code> 比较，≤该值时触发<strong>体动算法逻辑</strong>，否则用正常算法逻辑</td></tr></tbody></table><h4 id="_1-cali-pressure-decrease-percent" tabindex="-1"><code>[1]</code> <code>cali_pressure_decrease_percent</code> <a class="header-anchor" href="#_1-cali-pressure-decrease-percent" aria-label="Permalink to “[1] cali_pressure_decrease_percent”">​</a></h4><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>类别</td><td>工程变量</td></tr><tr><td>含义</td><td>标定的两次枕高压强变化<strong>负向百分比</strong>（压强减少时，P2&lt;P1）</td></tr><tr><td>默认值</td><td>5%</td></tr><tr><td>取值范围</td><td>0–100（整数）</td></tr><tr><td>数据类型</td><td>1 字节整数</td></tr><tr><td>用途</td><td>与两次枕高压强变化率 <code>(P1-P2)/P2</code> 比较，≤该值时触发<strong>体动算法逻辑</strong>，否则用正常算法逻辑</td></tr></tbody></table><h4 id="_2-3-max-pressure-protect-value" tabindex="-1"><code>[2-3]</code> <code>max_pressure_protect_value</code> <a class="header-anchor" href="#_2-3-max-pressure-protect-value" aria-label="Permalink to “[2-3] max_pressure_protect_value”">​</a></h4><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>类别</td><td>工程变量</td></tr><tr><td>含义</td><td>气囊最大压强保护值（防止过压的安全阈值）</td></tr><tr><td>默认值</td><td>出厂确认</td></tr><tr><td>取值范围</td><td>2 字节整数范围</td></tr><tr><td>数据类型</td><td>2 字节整数</td></tr><tr><td>用途</td><td>限制气囊压强不超过该值，保障设备安全</td></tr></tbody></table><h4 id="_4-pressure-sample-period" tabindex="-1"><code>[4]</code> <code>pressure_sample_period</code> <a class="header-anchor" href="#_4-pressure-sample-period" aria-label="Permalink to “[4] pressure_sample_period”">​</a></h4><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>类别</td><td>工程变量</td></tr><tr><td>含义</td><td>压强检测周期（两次采样的时间间隔）</td></tr><tr><td>默认值</td><td>5 秒</td></tr><tr><td>取值范围</td><td>1 字节整数范围</td></tr><tr><td>数据类型</td><td>1 字节整数</td></tr><tr><td>用途</td><td>周期采样压强，记录并与上次值比较以判断睡姿</td></tr></tbody></table><h4 id="_5-pressure-stable-percent" tabindex="-1"><code>[5]</code> <code>pressure_stable_percent</code> <a class="header-anchor" href="#_5-pressure-stable-percent" aria-label="Permalink to “[5] pressure_stable_percent”">​</a></h4><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>类别</td><td>工程变量</td></tr><tr><td>含义</td><td>气压稳定判断的百分比阈值（目标压强的允许波动范围）</td></tr><tr><td>默认值</td><td>±10%</td></tr><tr><td>取值范围</td><td>1 字节整数范围</td></tr><tr><td>数据类型</td><td>1 字节整数</td></tr><tr><td>用途</td><td>气压进入目标压强的 <strong>±该百分比范围</strong> 时，认为达到目标压强</td></tr></tbody></table><h4 id="_6-pressure-stable-duration" tabindex="-1"><code>[6]</code> <code>pressure_stable_duration</code> <a class="header-anchor" href="#_6-pressure-stable-duration" aria-label="Permalink to “[6] pressure_stable_duration”">​</a></h4><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>类别</td><td>工程变量</td></tr><tr><td>含义</td><td>气压稳定判断的持续时间阈值（需持续稳定的时长）</td></tr><tr><td>默认值</td><td>5 秒</td></tr><tr><td>取值范围</td><td>1 字节整数范围</td></tr><tr><td>数据类型</td><td>1 字节整数</td></tr><tr><td>用途</td><td>气压进入目标范围后，<strong>持续该时长</strong> 则认为达到稳定目标压强</td></tr></tbody></table><h4 id="_7-total-adjust-count-per-sleep" tabindex="-1"><code>[7]</code> <code>total_adjust_count_per_sleep</code> <a class="header-anchor" href="#_7-total-adjust-count-per-sleep" aria-label="Permalink to “[7] total_adjust_count_per_sleep”">​</a></h4><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>类别</td><td>业务变量</td></tr><tr><td>含义</td><td>一次完整睡眠的总干预次数</td></tr><tr><td>默认值</td><td>0（不限次数）</td></tr><tr><td>取值范围</td><td>1 字节整数范围</td></tr><tr><td>数据类型</td><td>1 字节整数</td></tr><tr><td>用途</td><td>记录单次睡眠的干预次数；<strong>0 表示不限次数</strong>，&gt;0 表示限制总次数</td></tr></tbody></table><h4 id="_8-base-pillow-height" tabindex="-1"><code>[8]</code> <code>base_pillow_height</code> <a class="header-anchor" href="#_8-base-pillow-height" aria-label="Permalink to “[8] base_pillow_height”">​</a></h4><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>类别</td><td>用户变量（UI）</td></tr><tr><td>含义</td><td>基础枕高（用户初始睡眠的枕头高度，取值来自标定模式）</td></tr><tr><td>默认值</td><td>第一次使用用户选择</td></tr><tr><td>取值范围</td><td>0–6（整数）</td></tr><tr><td>数据类型</td><td>1 字节整数</td></tr><tr><td>用途</td><td>人躺卧时的初始高度；<strong>0 表示不调节（最低高度）</strong>，1–6 为可调档位（来自标定模式结果）</td></tr></tbody></table><h3 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to “说明”">​</a></h3><ol><li><strong>数据类型</strong>：<code>1 字节整数</code> 范围通常为 0–255，<code>2 字节整数</code> 范围通常为 0–65535（具体依系统实现调整）。</li><li><strong>特殊值</strong>： <ul><li><code>total_adjust_count_per_sleep = 0</code>：单次睡眠干预次数不限</li><li><code>base_pillow_height = 0</code>：不调节枕高（使用最低高度）</li></ul></li><li><strong>工程变量</strong>： <ul><li><code>cali_pressure_increase_percent</code> / <code>cali_pressure_decrease_percent</code> 通过两次枕高（P1→P2）的压强变化方向与阈值比较，动态切换算法逻辑（体动 / 正常）</li><li><code>pressure_stable_percent</code> + <code>pressure_stable_duration</code> 联合判断气压是否稳定达标（先进入范围，再持续时长）</li></ul></li></ol><hr><h2 id="体动卧姿自动匹配参数" tabindex="-1">体动卧姿自动匹配参数 <a class="header-anchor" href="#体动卧姿自动匹配参数" aria-label="Permalink to “体动卧姿自动匹配参数”">​</a></h2><table tabindex="0"><thead><tr><th>偏移</th><th>变量名</th><th>默认值</th></tr></thead><tbody><tr><td><code>[9]</code></td><td><code>motion_detect_interval</code></td><td>1 秒</td></tr><tr><td><code>[10]</code></td><td><code>motion_cont_threshold</code></td><td>1 秒</td></tr><tr><td><code>[11]</code></td><td><code>change_height_motion_cnt</code></td><td>2</td></tr><tr><td><code>[12]</code></td><td><code>motion_interv_window</code></td><td>5 秒</td></tr><tr><td><code>[13]</code></td><td>（保留）</td><td>—</td></tr></tbody></table><h4 id="_9-motion-detect-interval" tabindex="-1"><code>[9]</code> <code>motion_detect_interval</code> <a class="header-anchor" href="#_9-motion-detect-interval" aria-label="Permalink to “[9] motion_detect_interval”">​</a></h4><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>类别</td><td>体动卧姿自动匹配</td></tr><tr><td>含义</td><td>体动检测周期（两次体动检测的时间间隔，单位：秒）</td></tr><tr><td>默认值</td><td>1</td></tr><tr><td>取值范围</td><td>0–255</td></tr><tr><td>数据类型</td><td>1 字节整数</td></tr><tr><td>用途</td><td>每间隔 X 秒执行一次体动状态检测</td></tr></tbody></table><h4 id="_10-motion-cont-threshold" tabindex="-1"><code>[10]</code> <code>motion_cont_threshold</code> <a class="header-anchor" href="#_10-motion-cont-threshold" aria-label="Permalink to “[10] motion_cont_threshold”">​</a></h4><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>类别</td><td>体动卧姿自动匹配</td></tr><tr><td>含义</td><td>体动检测周期内，多少秒体动算一次「连续体动」（单位：秒）</td></tr><tr><td>默认值</td><td>1</td></tr><tr><td>取值范围</td><td>0–255</td></tr><tr><td>数据类型</td><td>1 字节整数</td></tr><tr><td>用途</td><td>单周期内体动持续 ≥ 该秒数，计为一次连续体动</td></tr></tbody></table><h4 id="_11-change-height-motion-cnt" tabindex="-1"><code>[11]</code> <code>change_height_motion_cnt</code> <a class="header-anchor" href="#_11-change-height-motion-cnt" aria-label="Permalink to “[11] change_height_motion_cnt”">​</a></h4><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>类别</td><td>体动卧姿自动匹配</td></tr><tr><td>含义</td><td>改变气囊高度需要的「连续体动」累计次数</td></tr><tr><td>默认值</td><td>2</td></tr><tr><td>取值范围</td><td>0–255</td></tr><tr><td>数据类型</td><td>1 字节整数</td></tr><tr><td>用途</td><td>累计达到该次数后，触发气囊高度自动调整</td></tr></tbody></table><h4 id="_12-motion-interv-window" tabindex="-1"><code>[12]</code> <code>motion_interv_window</code> <a class="header-anchor" href="#_12-motion-interv-window" aria-label="Permalink to “[12] motion_interv_window”">​</a></h4><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>类别</td><td>体动卧姿自动匹配</td></tr><tr><td>含义</td><td>体动干预窗口时间（单位：秒）</td></tr><tr><td>默认值</td><td>5</td></tr><tr><td>取值范围</td><td>0–255</td></tr><tr><td>数据类型</td><td>1 字节整数</td></tr><tr><td>用途</td><td>检测到满足条件后，在该窗口内允许执行干预动作</td></tr></tbody></table><h4 id="_13-保留" tabindex="-1"><code>[13]</code> 保留 <a class="header-anchor" href="#_13-保留" aria-label="Permalink to “[13] 保留”">​</a></h4><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>类别</td><td>保留</td></tr><tr><td>含义</td><td>保留字节</td></tr><tr><td>默认值</td><td>—</td></tr><tr><td>取值范围</td><td>—</td></tr><tr><td>数据类型</td><td>1 字节</td></tr><tr><td>用途</td><td>不要当功能用</td></tr></tbody></table>`,37)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};